import{_ as a,c as t,a2 as o,o as i}from"./chunks/framework.YPpNXepj.js";const p=JSON.parse('{"title":"Two-Factor Authentication (2FA) Overview","description":"","frontmatter":{},"headers":[],"relativePath":"two-factor-auth.md","filePath":"two-factor-auth.md"}'),r={name:"two-factor-auth.md"};function n(s,e,c,u,l,d){return i(),t("div",null,e[0]||(e[0]=[o('<h1 id="two-factor-authentication-2fa-overview" tabindex="-1">Two-Factor Authentication (2FA) Overview <a class="header-anchor" href="#two-factor-authentication-2fa-overview" aria-label="Permalink to &quot;Two-Factor Authentication (2FA) Overview&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Two-Factor Authentication (2FA) adds an extra layer of security to your account. It requires a second form of verification in addition to your password, making it significantly harder for unauthorized users to access your account.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Multiple Authentication Methods</strong>: Use authenticator apps like Google Authenticator, Authy, or password managers with 2FA support.</li><li><strong>Backup Codes</strong>: Generate and download backup codes for account recovery.</li><li><strong>QR Code and Manual Entry</strong>: Scan a QR code or manually enter a security key for setup.</li><li><strong>Email Notifications</strong>: Receive emails for 2FA activation, deactivation, and backup code events.</li></ul><h2 id="setting-up-2fa" tabindex="-1">Setting Up 2FA <a class="header-anchor" href="#setting-up-2fa" aria-label="Permalink to &quot;Setting Up 2FA&quot;">​</a></h2><ol><li>Navigate to your account security settings.</li><li>Choose to enable 2FA.</li><li>Scan the QR code or manually enter the security key in your authenticator app.</li><li>Enter the 6-digit code to verify and enable 2FA.</li><li>Save your backup codes securely.</li></ol><h2 id="recommended-password-managers-with-2fa-support" tabindex="-1">Recommended Password Managers with 2FA Support <a class="header-anchor" href="#recommended-password-managers-with-2fa-support" aria-label="Permalink to &quot;Recommended Password Managers with 2FA Support&quot;">​</a></h2><ul><li>1Password</li><li>Bitwarden</li></ul><p>These offer secure storage for both your passwords and 2FA codes.</p><h2 id="using-2fa" tabindex="-1">Using 2FA <a class="header-anchor" href="#using-2fa" aria-label="Permalink to &quot;Using 2FA&quot;">​</a></h2><ul><li>You&#39;ll be prompted for a 2FA code after entering your password.</li><li>This prompt appears once every 30 days or if there&#39;s a significant IP change.</li><li>The system uses encrypted cookies to remember your authentication status.</li></ul><h2 id="backup-and-recovery" tabindex="-1">Backup and Recovery <a class="header-anchor" href="#backup-and-recovery" aria-label="Permalink to &quot;Backup and Recovery&quot;">​</a></h2><ul><li>Download your backup codes and store them securely.</li><li>Use a backup code if you can&#39;t access your authenticator app.</li><li>Each backup code can only be used once.</li></ul><h2 id="troubleshooting-tips" tabindex="-1">Troubleshooting Tips <a class="header-anchor" href="#troubleshooting-tips" aria-label="Permalink to &quot;Troubleshooting Tips&quot;">​</a></h2><ul><li>Can&#39;t scan the QR code? Use the manual entry option with the provided security key.</li><li>Seeing &quot;Invalid code&quot;? Ensure your device&#39;s time is correctly synchronized.</li></ul><h2 id="important-notes" tabindex="-1">Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to &quot;Important Notes&quot;">​</a></h2><ul><li>You&#39;ll receive email notifications for 2FA activation, deactivation, backup code regeneration, and viewing.</li><li>Backup codes older than a year trigger a weekly reminder email to regenerate them.</li><li>For account security, we recommend using a password manager that supports 2FA.</li></ul><h2 id="emergency-measures" tabindex="-1">Emergency Measures <a class="header-anchor" href="#emergency-measures" aria-label="Permalink to &quot;Emergency Measures&quot;">​</a></h2><p>In case of emergencies, administrators can disable 2FA for a user with the following command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>php artisan vanguard:disable-two-factor {user_email}</span></span></code></pre></div><p>This should only be used in exceptional circumstances and with proper verification.</p><h2 id="automatic-notifications" tabindex="-1">Automatic Notifications <a class="header-anchor" href="#automatic-notifications" aria-label="Permalink to &quot;Automatic Notifications&quot;">​</a></h2><p>Our system runs a weekly check for outdated backup codes that sends reminder emails to users with backup codes older than one year, encouraging them to regenerate their codes for enhanced security.</p><p>Remember, 2FA significantly enhances your account security. We strongly recommend enabling it and keeping your authentication methods and backup codes up to date.</p>',25)]))}const m=a(r,[["render",n]]);export{p as __pageData,m as default};
